function numberEncode(input) {
    let out = '';
    for (const ch of input) {
      const ds = String(ch.codePointAt(0));
      for (let i = 0; i < ds.length; i++) {
        out += '喵'.repeat(+ds[i]) + (i === ds.length - 1 ? '！' : '？');
      }
    }
    return out;
  }

